import { useEffect, useState } from 'react';
import{ useParams , useNavigate } from 'react-router-dom';
import './movie-info.css';
impor

import api from '../../services/api';


function Movie() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [movie, setMovie] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
      async function LoadMovie() {
    try {
      const response = await api.get(`/movie/${id}`, {
        params: {
          api_key: '33bbe824b4f390224fb92dcc55b00ea8',
          language: 'pt-BR'
        }
      });

      setMovie(response.data);
      setLoading(false);

    } catch (error) {
      console.log(error.response);
      console.log("Filme não encontrado");
      navigate("/", { replace: true });
      return;
    }
  }

    LoadMovie();

    }, [navigate, id]);

    function SalvarFilme() {
      const minhaLista = localStorage.getItem("@primeflix");
      let filmesSalvos = JSON.parse(minhaLista) || [];

      const hasFilme = filmesSalvos.some((filmeSalvo) => filmeSalvo.id === movie.id);

      if(hasFilme) {
        alert("Esse filme já está na sua lista!");
        return;
      }

      filmesSalvos.push(movie);
      localStorage.setItem("@primeflix", JSON.stringify(filmesSalvos));
      alert("Filme salvo com sucesso!");
    }

    if(loading) {
      return (
        <div className="loading">
          <h1>Carregando detalhes...</h1>
        </div>
      );
    }

    console.log(movie);
        
  return (
    <div className="movie-info">
        <h1>{movie.title}</h1>
        <img src={`https://image.tmdb.org/t/p/original/${movie.backdrop_path}`} alt={movie.title} />
        <h3>Sinopse</h3>
        <span>{movie.overview}</span>
        <strong>Avaliação: {movie.vote_average} / 10</strong>

        <div className="area-buttons">
          <button onClick={SalvarFilme}>Salvar</button>
          <button className="">
            <a href={`https://www.youtube.com/results?search_query=${movie.title} Trailer`} target="_blank" rel="external">
            Trailer
          </a></button>
        </div>
      </div>
  );
}

export default Movie;
